INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_ea21275ac301017949b3d1ae","wiki/sources/inb-2027-anlage-5-10-foerderrichtlinie-data.md",0,"Seite 1","Bundesanzeiger Bekanntmachung\n\nSeite 1 von 6\n\n*240511001237* * 8 3 0 2 8 1 *\n\nV4\n\n*240511001237* 1 7 . 0 6 . 2 0 2 4 0 8 : 5 3 : 4 6 *830281*\n\nBundesministerium\n\nfÃ¼r Digitales und Verkehr\n\nBekanntmachung\n\nder Richtlinie\n\nzur FÃ¶rderung des SchienengÃ¼terverkehrs\n\nÃ¼ber eine anteilige Finanzierung\n\nder genehmigten Trassenentgelte (af-TP)\n\nVom 21. Mai 2024\n\nPrÃ¤ambel\n\nFÃ¼r ein nachhaltiges und leistungsfÃ¤higes Verkehrssystem, das sowohl Ã¶kologischen als auch sozialen und Ã¶konomischen Belangen Rechnung trÃ¤gt, ist der klimaschonende, energieeffiziente und bereits heute weitgehend â€želektromobileâ€œ Schienenverkehr eine unverzichtbare SÃ¤ule. Die Eisenbahnen leisten als emissionsarmer VerkehrstrÃ¤ger einen\n\nerheblichen Beitrag zur Erreichung der nationalen und europÃ¤ischen Klimaschutzziele. Dies gilt auch und insbesondere im Hinblick auf den SchienengÃ¼terverkehr (SGV). Als Beitrag zur Erreichung der nationalen Zielstellung im Aktionsprogramm Klimaschutz 2020, fortgefÃ¼hrt durch das Klimaschutzprogramm 2030, fÃ¶rdert das Bundesministerium\n\nfÃ¼r Digitales und Verkehr die WettbewerbsfÃ¤higkeit des SGV durch den Masterplan SGV, der am 23. Juni 2017 verÃ¶ffentlicht wurde. Diese Richtlinie setzt die im Masterplan SGV vorgesehene FÃ¶rderung des SGV Ã¼ber eine anteilige\n\nFinanzierung der Trassenentgelte um.\n\nDie FÃ¶rderung im Rahmen dieser Richtlinie knÃ¼pft an die von der Bundesnetzagentur (BNetzA) genehmigten Trassenentgelte an und trÃ¤gt zur Harmonisierung der Wettbewerbsbedingungen im europÃ¤ischen SGV bei. Die FÃ¶rderung\n\nschafft Anreize zur Sicherung der bestehenden SchienengÃ¼terverkehre auf der Schiene sowie Anreize, GÃ¼terverkehre\n\nvon der StraÃŸe auf die Schiene zu verlagern. Hierzu werden den im SGV tÃ¤tigen Unternehmen Ã¼ber die DB InfraGO AG",235,"{\"canonical_url\":null,\"normalized_sha256\":\"8228a85ae58abdd2203cec7ce6f7070955ae0ce53701ccbfbcc071fabf837a0f\",\"page\":1,\"source_id\":\"src_cbaf01091305484871df\",\"source_sha256\":\"a6b266cc839af1dd42fa2aa16f4d7d8e8cdb5bbfa59b0305fbe0307e797602b6\",\"source_version_id\":\"sv_327f028261951516dbce8502\"}","a671f1d27e4fefae57268415e691b3adaca68576555c453512995bb3682a9164"],["chunk_b6127952388d322756ec8c0d","wiki/sources/inb-2027-anlage-5-10-foerderrichtlinie-data.md",1,"Seite 1","Haushaltsmittel des Bundes zur VerfÃ¼gung gestellt. Die Ausreichung der FÃ¶rdermittel knÃ¼pft an den Trassenbestellprozess und die Trassenentgeltabrechnung der DB InfraGO AG an.\n\nDie Gemeinschaftlichen Leitlinien der EU-Kommission fÃ¼r staatliche Beihilfen an Eisenbahnunternehmen\n\n(2008/C184/07) (Eisenbahnleitlinien) sehen vor, dass unter Wahrung des Wettbewerbs bis zu 30 Prozent der Gesamtkosten des Schienenverkehrs und 50 Prozent der beihilfefÃ¤higen Kosten durch Zuwendungen gedeckt werden dÃ¼rfen.\n\nDiese Vorgaben des Europarechts werden in dieser FÃ¶rderrichtlinie eingehalten.\n\nÂ§ 1\n\nFÃ¶rderziel und Zuwendungszweck\n\n(1) Mit der FÃ¶rderung wird ein wesentlicher Anreiz zur Verbesserung der WettbewerbsfÃ¤higkeit des umweltfreundlicheren SGV gegenÃ¼ber dem GÃ¼tertransport auf der StraÃŸe gegeben. Ziel ist es, den Modal Split des SGV zu halten\n\nund zu verbessern.\n\n(2) Beihilferechtliche Grundlage fÃ¼r die FÃ¶rderrichtlinie ist Artikel 93 des Vertrags Ã¼ber die Arbeitsweise der EuropÃ¤ischen Union (AEUV) in Verbindung mit Nummer 6 der von der EuropÃ¤ischen Kommission beschlossenen Gemeinschaftlichen Leitlinien fÃ¼r staatliche Beihilfen an Eisenbahnunternehmen (Eisenbahnleitlinien, Mitteilung der Kommission â€“ Gemeinschaftliche Leitlinien fÃ¼r staatliche Beihilfen an Eisenbahnunternehmen, 2008/C 184/07). Diese Richtlinie\n\nwird gemÃ¤ÃŸ Artikel 108 Absatz 3 AEUV der EuropÃ¤ischen Kommission notifiziert.\n\n(3) Der Bund gewÃ¤hrt nach MaÃŸgabe dieser Richtlinie sowie den Â§Â§ 23, 44 der Bundeshaushaltsordnung (BHO) und\n\nden dazu erlassenen Allgemeinen Verwaltungsvorschriften eine anteilige FÃ¶rderung der Netto-BetrÃ¤ge der von den",202,"{\"canonical_url\":null,\"normalized_sha256\":\"8228a85ae58abdd2203cec7ce6f7070955ae0ce53701ccbfbcc071fabf837a0f\",\"page\":1,\"source_id\":\"src_cbaf01091305484871df\",\"source_sha256\":\"a6b266cc839af1dd42fa2aa16f4d7d8e8cdb5bbfa59b0305fbe0307e797602b6\",\"source_version_id\":\"sv_327f028261951516dbce8502\"}","08af7617d3252ed701856295d5777f95dc031cfef947d4161a270230856f1c54"],["chunk_49ca070f1c8918248e494932","wiki/sources/inb-2027-anlage-5-10-foerderrichtlinie-data.md",2,"Seite 1","bundeseigenen Betreibern der Schienenwege auf der Basis der von der BNetzA genehmigten Entgeltlisten in Rechnung gestellten Trassenentgelte fÃ¼r tatsÃ¤chlich erbrachte Betriebsleistungen in Trassenkilometern (Betriebsleistungen)\n\nentsprechend der Abrechnung nach den Infrastrukturnutzungsbedingungen der DB InfraGO AG (INB) beziehungsweise im Fahrplanjahr 2024 nach den Nutzungsbedingungen Netz der DB InfraGO AG (NBN). Die Finanzierungskompetenz des Bundes ergibt sich aus Artikel 73 Absatz 1 Nummer 6a in Verbindung mit Artikel 87e des Grundgesetzes.\n\nEin Anspruch auf GewÃ¤hrung der Zuwendung besteht nicht. Vielmehr entscheidet die BewilligungsbehÃ¶rde aufgrund\n\nihres pflichtgemÃ¤ÃŸen Ermessens im Rahmen der verfÃ¼gbaren Haushaltsmittel.\n\n(4) Die FÃ¶rderung umfasst Betriebsleistungen im Zeitraum 28. Juni 2024 bis 30. November 2028.\n\nÂ§ 2\n\nGegenstand der FÃ¶rderung\n\n(1) GefÃ¶rdert wird die DurchfÃ¼hrung von GÃ¼terverkehren auf Eisenbahnstrecken (Betriebsleistungen auf der Schiene)\n\nin Deutschland im Geltungsbereich der Trassenpreissyste